const codeengine = require('codeengine');

async function sendRequest(method, url, body) {
  const res = await codeengine.sendRequest(method, url, body);
  if (res.status >= 400) {
    throw new Error(`${method} ${url}: ${res.status} - ${res.body}`);
  }
  return res.body ? JSON.parse(res.body) : null;
}

/**
 * Get all datasets used on a given Domo page.
 * @param {string} pageId - The Domo page ID
 * @returns {object} - { datasets: [{ id, name, description, rows }] }
 */
async function getPageDatasets(pageId) {
  if (!pageId) throw new Error('pageId is required');

  const data = await sendRequest('GET', `/api/content/v1/datasources/pages/${pageId}`);
  const sources = data?.dataSources || [];

  return {
    datasets: sources.map(ds => ({
      id: String(ds.id),
      name: ds.name || ds.displayName || `Dataset ${ds.id}`,
      description: ds.description || '',
      rows: ds.rows || ds.rowCount || 0,
    })),
  };
}

/**
 * Get all cards on a given Domo page.
 * @param {string} pageId - The Domo page ID
 * @returns {object} - { cards: [{ id, title, type }] }
 */
async function getPageCards(pageId) {
  if (!pageId) throw new Error('pageId is required');

  const data = await sendRequest('GET', `/api/content/v3/stacks/${pageId}/cards`);
  const cards = data?.cards || [];

  return {
    cards: cards
      .filter(c => c.id != null)
      .map(c => ({
        id: Number(c.id),
        title: c.title || c.name || `Card ${c.id}`,
        type: c.type || c.chartType || '',
      })),
  };
}

/**
 * Get schema (columns) for a dataset.
 * @param {string} datasetId - The dataset UUID
 * @returns {object} - { columns: [{ name, type }] }
 */
async function getDatasetSchema(datasetId) {
  if (!datasetId) throw new Error('datasetId is required');

  const data = await sendRequest('GET', `/api/data/v3/datasources/${datasetId}?part=columns`);
  const columns = data?.columns || data?.schemas?.[0]?.columns || [];

  return {
    columns: columns.map(col => ({
      name: col.name || col.columnName || '',
      type: col.type || 'STRING',
    })),
  };
}

/**
 * Execute a SQL query against a dataset and return results.
 * @param {string} datasetId - The dataset UUID
 * @param {string} sql - The SQL query to execute
 * @returns {object} - { columns: string[], rows: any[][], numRows: number }
 */
async function queryDataset(datasetId, sql) {
  if (!datasetId) throw new Error('datasetId is required');
  if (!sql) throw new Error('sql is required');

  const data = await sendRequest('POST', `/api/query/v1/execute/${datasetId}`, { sql });

  return {
    columns: data?.columns || [],
    rows: data?.rows || [],
    numRows: data?.numRows || (data?.rows?.length ?? 0),
  };
}

module.exports = { getPageDatasets, getPageCards, getDatasetSchema, queryDataset };
